local P,RS,W,CAM,LP,CG,UIS,VIM,TS,HS,ST = game:GetService("Players"),game:GetService("RunService"),game:GetService("Workspace"),game:GetService("Workspace").CurrentCamera,game:GetService("Players").LocalPlayer,game:GetService("CoreGui"),game:GetService("UserInputService"),game:GetService("VirtualInputManager"),game:GetService("TweenService"),game:GetService("HttpService"),game:GetService("Stats")
local S={Enabled=true,ShowBox=true,ShowName=true,ShowDistance=true,ShowHealth=true,ShowSkeleton=false,ColorVisible=Color3.fromRGB(0,255,0),ColorBehindWall=Color3.fromRGB(255,0,0),TB_Enabled=false,TB_Delay=0.05,AB_Enabled=false,AB_FOV=150,AB_Smooth=0.2,MaxDistance=1000}
_G.ESP_CONFIG = S
local function vis(wp) local pr=RaycastParams.new() pr.FilterType=Enum.RaycastFilterType.Exclude local ex={CAM} if LP.Character then table.insert(ex,LP.Character) end for _,p in ipairs(P:GetPlayers()) do if p.Character then table.insert(ex,p.Character) end end pr.FilterDescendantsInstances=ex local r=W:Raycast(CAM.CFrame.Position,wp-CAM.CFrame.Position,pr) if not r then return true end local m=r.Instance and r.Instance:FindFirstAncestorOfClass("Model") return not (m and m:FindFirstChildOfClass("Humanoid")) end
local function w2v(p) local sp,on=CAM:WorldToViewportPoint(p) return Vector2.new(sp.X,sp.Y),sp.Z,on end
local function nD(c,pr) local ok,d=pcall(function() return Drawing.new(c) end) if not ok or not d then return nil end for k,v in pairs(pr or {}) do pcall(function() d[k]=v end) end return d end
local DR={} local R15={{"Head","UpperTorso"},{"UpperTorso","LeftUpperArm"},{"LeftUpperArm","LeftLowerArm"},{"UpperTorso","RightUpperArm"},{"RightUpperArm","RightLowerArm"},{"LowerTorso","LeftUpperLeg"},{"LeftUpperLeg","LeftLowerLeg"},{"LowerTorso","RightUpperLeg"},{"RightUpperLeg","RightLowerLeg"}}
local function createV(m) local d={box=S.ShowBox and nD("Square",{Thickness=1,Filled=false,Visible=false}) or nil,name=S.ShowName and nD("Text",{Center=true,Outline=true,Size=14,Font=2,Visible=false}) or nil,dist=S.ShowDistance and nD("Text",{Center=true,Outline=true,Size=12,Font=2,Visible=false}) or nil,hpBg=S.ShowHealth and nD("Square",{Thickness=1,Filled=true,Visible=false}) or nil,hpFg=S.ShowHealth and nD("Square",{Thickness=0,Filled=true,Visible=false}) or nil,bones={}} if S.ShowSkeleton then for i=1,#R15 do local l=nD("Line",{Thickness=1,Visible=false}) if l then d.bones[i]=l end end end DR[m]=d end
local function hideV(d) if d.box then d.box.Visible=false end if d.name then d.name.Visible=false end if d.dist then d.dist.Visible=false end if d.hpBg then d.hpBg.Visible=false end if d.hpFg then d.hpFg.Visible=false end for _,l in pairs(d.bones) do l.Visible=false end end
local function destroyV(m) local d=DR[m] if not d then return end for _,v in pairs(d) do if type(v)=="table" then for _,l in pairs(v) do pcall(function() l:Remove() end) end elseif v then pcall(function() v:Remove() end) end end DR[m]=nil end
local function clearAll() for m in pairs(DR) do destroyV(m) end end
local lastC=0 local function tbLog() if not S.TB_Enabled or tick()-lastC<S.TB_Delay then return end local vp=CAM.ViewportSize local cx,cy=vp.X/2,vp.Y/2 local ur=CAM:ViewportPointToRay(cx,cy) local pr=RaycastParams.new() pr.FilterType=Enum.RaycastFilterType.Exclude pr.FilterDescendantsInstances={CAM,LP.Character} local res=W:Raycast(ur.Origin,ur.Direction*2000,pr) if res and res.Instance then local hm=res.Instance:FindFirstAncestorOfClass("Model") if hm and hm:FindFirstChildOfClass("Humanoid") then lastC=tick() pcall(function() VIM:SendMouseButtonEvent(cx,cy,0,true,game,1) task.wait(0.01) VIM:SendMouseButtonEvent(cx,cy,0,false,game,1) end) local t=LP.Character and LP.Character:FindFirstChildOfClass("Tool") if t then t:Activate() end end end end
local function abLog() if not S.AB_Enabled then return end local cls=nil local md=S.AB_FOV local vp=CAM.ViewportSize for _,p in ipairs(P:GetPlayers()) do if p~=LP and p.Character and p.Character:FindFirstChild("Head") then local h=p.Character:FindFirstChildOfClass("Humanoid") if h and h.Health>0 and p.Team~=LP.Team then local sp,on=CAM:WorldToViewportPoint(p.Character.Head.Position) if on then local d=(Vector2.new(sp.X,sp.Y)-Vector2.new(vp.X/2,vp.Y/2)).Magnitude if d<md then md=d cls=p.Character.Head end end end end end if cls and vis(cls.Position) then local cf=CFrame.new(CAM.CFrame.Position,cls.Position) if S.AB_Smooth>0 then CAM.CFrame=CAM.CFrame:Lerp(cf,S.AB_Smooth) else CAM.CFrame=cf end end end
local function updESP() local ct={} for _,p in ipairs(P:GetPlayers()) do if p~=LP and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then ct[p.Character]={} end end for m in pairs(DR) do if not ct[m] or not m.Parent then destroyV(m) end end local vp=CAM.ViewportSize for m in pairs(ct) do if not DR[m] then createV(m) end local d=DR[m] local hrp=m:FindFirstChild("HumanoidRootPart") local head=m:FindFirstChild("Head") if not hrp or not head then hideV(d) continue end local rp=hrp.Position local di=(CAM.CFrame.Position-rp).Magnitude if di>S.MaxDistance then hideV(d) continue end local c=vis(rp) and S.ColorVisible or S.ColorBehindWall local sp,dp,on=w2v(rp) local hsp,hdp=w2v(head.Position+Vector3.new(0,1,0)) local fsp,fdp=w2v(hrp.Position-Vector3.new(0,3,0)) if not on or dp<=0 or hdp<=0 or fdp<=0 then hideV(d) continue end local h=math.abs(fsp.Y-hsp.Y) local w=h*0.6 if h<5 then hideV(d) continue end local x=sp.X-(w/2) local y=hsp.Y if d.box then d.box.Visible=S.ShowBox d.box.Color=c d.box.Size=Vector2.new(w,h) d.box.Position=Vector2.new(x,y) end if d.name then d.name.Visible=S.ShowName d.name.Text=m.Name d.name.Color=c d.name.Position=Vector2.new(sp.X,y-18) end if d.dist then d.dist.Visible=S.ShowDistance d.dist.Text=string.format("[%d]",math.floor(di)) d.dist.Color=c d.dist.Position=Vector2.new(sp.X,y+h+2) end local hum=m:FindFirstChildOfClass("Humanoid") if d.hpBg and d.hpFg and hum and S.ShowHealth then local pct=math.clamp(hum.Health/hum.MaxHealth,0,1) d.hpBg.Visible=true d.hpBg.Size=Vector2.new(3,h) d.hpBg.Position=Vector2.new(x-6,y) d.hpBg.Color=Color3.new(0,0,0) d.hpFg.Visible=true d.hpFg.Size=Vector2.new(3,h*pct) d.hpFg.Position=Vector2.new(x-6,y+h*(1-pct)) d.hpFg.Color=pct<0.3 and Color3.fromRGB(255,0,0) or Color3.fromRGB(0,255,0) else if d.hpBg then d.hpBg.Visible=false end if d.hpFg then d.hpFg.Visible=false end end if S.ShowSkeleton and d.bones then for i,pr in ipairs(R15) do local l=d.bones[i] if l then local a=m:FindFirstChild(pr[1]) local b=m:FindFirstChild(pr[2]) if a and b and a:IsA("BasePart") and b:IsA("BasePart") then local pa,da=w2v(a.Position) local pb,db=w2v(b.Position) if da>0 and db>0 then l.Visible=true l.From=pa l.To=pb l.Color=c else l.Visible=false end else l.Visible=false end end end end end end
local frames=0 local lastT=tick()
RS.RenderStepped:Connect(function() frames=frames+1 if tick()-lastT>=1 then local fps=math.floor(frames/(tick()-lastT)) local ping=0 pcall(function() ping=math.floor(ST.Network.ServerStatsItem["Data Ping"]:GetValue()) end) if _G.UPDATE_HUD then _G.UPDATE_HUD(fps,ping) end frames=0 lastT=tick() end abLog() tbLog() if S.Enabled then updESP() else for m,d in pairs(DR) do hideV(d) end end end)
loadstring(game:HttpGet("https://raw.githubusercontent.com/s1nkyy987653e3-sketch/v8.1/refs/heads/main/ui.lua"))()
